}

/** post(x,z,y0=2,y1=4): dark_oak_log, axis=y. */
export function post(g, x, z, y0 = 2, y1 = 4) {
  for (const y of range(y0, y1)) put(g, x, y, z, ...B.log("dark_oak", "y"));
